with metrics as (select id, customer_id, end_date, lead(monthly_fee, 1) over (order by start_date, id) as next_monthly_fee, last_value(monthly_fee) ignore nulls over (partition by plan order by monthly_fee, id rows between unbounded preceding and current row) as last_known_monthly_fee, row_number() over (order by monthly_fee, id) as row_seq, round(monthly_fee / sum(monthly_fee) over (partition by status), 4) as monthly_fee_share, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share_2 from subscriptions where monthly_fee < 220) select customer_id, date_trunc('quarter', end_date) as quarter_start, avg(monthly_fee_share_2) as avg_monthly_fee_share_2, count(distinct id) as distinct_ids, approx_percentile(monthly_fee_share, array(0.25, 0.5, 0.75)) as monthly_fee_share_quartiles, percentile_approx(row_seq, 0.95) as row_seq_p95, min(monthly_fee_share) as min_monthly_fee_share, grouping(customer_id) as gid from metrics group by grouping sets ((customer_id, date_trunc('quarter', end_date)), (customer_id), ()) order by customer_id desc nulls last
